<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;500;600;700;800;900&family=Inter:wght@400;500;600&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --green: #2D6A4F;
      --green-light: #40916C;
      --green-pale: #D8F3DC;
      --orange: #F4A261;
      --orange-dark: #E76F51;
      --cream: #FEFAE0;
      --cream-dark: #F5EDD0;
      --text-dark: #1A3C2A;
      --text-mid: #4A6B5A;
      --text-light: #7A9B8A;
      --white: #FFFFFF;
      --shadow-sm: 0 2px 8px rgba(45,106,79,0.08);
      --shadow-md: 0 4px 20px rgba(45,106,79,0.12);
      --shadow-lg: 0 8px 40px rgba(45,106,79,0.16);
      --radius-sm: 12px;
      --radius-md: 20px;
      --radius-lg: 28px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', sans-serif;
      background: var(--cream);
      color: var(--text-dark);
      line-height: 1.6;
    }

    h1, h2, h3, h4, h5 {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      line-height: 1.2;
    }

    /* ── HEADER ── */
    header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(254,250,224,0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--cream-dark);
      box-shadow: var(--shadow-sm);
    }

    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      text-decoration: none;
      flex-shrink: 0;
    }

    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--green);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
    }

    .logo-text {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: 1.25rem;
      color: var(--green);
      letter-spacing: -0.02em;
    }

    nav {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    nav a {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 0.95rem;
      color: var(--text-mid);
      text-decoration: none;
      padding: 8px 16px;
      border-radius: 100px;
      transition: all 0.2s ease;
    }

    nav a:hover {
      background: var(--green-pale);
      color: var(--green);
    }

    .header-cta {
      background: var(--green) !important;
      color: var(--white) !important;
    }

    .header-cta:hover {
      background: var(--green-light) !important;
      color: var(--white) !important;
    }

    /* ── HERO ── */
    .hero {
      background: linear-gradient(135deg, var(--green) 0%, var(--green-light) 60%, #52B788 100%);
      padding: 80px 24px 100px;
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.04'%3E%3Ccircle cx='30' cy='30' r='20'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
      pointer-events: none;
    }

    .hero-blobs {
      position: absolute;
      inset: 0;
      pointer-events: none;
      overflow: hidden;
    }

    .hero-blob {
      position: absolute;
      border-radius: 50%;
      opacity: 0.12;
    }

    .hero-blob-1 {
      width: 500px; height: 500px;
      background: var(--orange);
      top: -150px; right: -100px;
    }

    .hero-blob-2 {
      width: 300px; height: 300px;
      background: var(--cream);
      bottom: -80px; left: 10%;
    }

    .hero-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
      position: relative;
    }

    .hero-content {}

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(255,255,255,0.15);
      color: var(--cream);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 0.85rem;
      padding: 6px 14px;
      border-radius: 100px;
      border: 1px solid rgba(255,255,255,0.25);
      margin-bottom: 20px;
      letter-spacing: 0.02em;
    }

    .hero h1 {
      font-size: clamp(2.4rem, 5vw, 3.6rem);
      color: var(--white);
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }

    .hero h1 span {
      color: var(--orange);
    }

    .hero p {
      font-size: 1.1rem;
      color: rgba(255,255,255,0.85);
      margin-bottom: 36px;
      max-width: 480px;
      line-height: 1.7;
    }

    .hero-buttons {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--orange);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1rem;
      padding: 14px 28px;
      border-radius: 100px;
      border: none;
      cursor: pointer;
      text-decoration: none;
      transition: all 0.2s ease;
      box-shadow: 0 4px 16px rgba(244,162,97,0.4);
    }

    .btn-primary:hover {
      background: var(--orange-dark);
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(244,162,97,0.5);
    }

    .btn-secondary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(255,255,255,0.15);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      padding: 14px 28px;
      border-radius: 100px;
      border: 1px solid rgba(255,255,255,0.35);
      cursor: pointer;
      text-decoration: none;
      transition: all 0.2s ease;
      backdrop-filter: blur(8px);
    }

    .btn-secondary:hover {
      background: rgba(255,255,255,0.25);
      transform: translateY(-2px);
    }

    .hero-visual {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }

    .hero-card {
      background: rgba(255,255,255,0.12);
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: var(--radius-md);
      backdrop-filter: blur(12px);
      overflow: hidden;
      transition: transform 0.3s ease;
    }

    .hero-card:hover { transform: translateY(-4px); }

    .hero-card-img {
      width: 100%;
      aspect-ratio: 4/3;
      object-fit: cover;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
    }

    .hero-card-img.produce { background: linear-gradient(135deg, #A7C957, #6A994E); }
    .hero-card-img.pantry { background: linear-gradient(135deg, #E9C46A, #F4A261); }
    .hero-card-img.dairy { background: linear-gradient(135deg, #ADE8F4, #48CAE4); }
    .hero-card-img.snacks { background: linear-gradient(135deg, #FFADAD, #FF6B6B); }

    .hero-card-body {
      padding: 12px 14px;
    }

    .hero-card-body p {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 0.85rem;
      color: var(--white);
      margin: 0;
    }

    .hero-card-body span {
      font-size: 0.75rem;
      color: rgba(255,255,255,0.65);
    }

    /* ── SECTION BASE ── */
    section { padding: 80px 24px; }

    .section-inner { max-width: 1280px; margin: 0 auto; }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-label {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 0.8rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--green);
      background: var(--green-pale);
      padding: 4px 12px;
      border-radius: 100px;
      margin-bottom: 12px;
    }

    .section-title {
      font-size: clamp(1.8rem, 3.5vw, 2.6rem);
      color: var(--text-dark);
      margin-bottom: 12px;
      letter-spacing: -0.02em;
    }

    .section-subtitle {
      font-size: 1.05rem;
      color: var(--text-light);
      max-width: 560px;
      margin: 0 auto;
      line-height: 1.7;
    }

    /* ── FEATURED PRODUCTS CAROUSEL ── */
    .featured-products {
      background: var(--white);
      padding: 80px 0;
    }

    .featured-products .section-inner {
      padding: 0 24px;
    }

    .carousel-wrapper {
      position: relative;
      margin-top: 8px;
    }

    .carousel-track-outer {
      overflow: hidden;
      border-radius: var(--radius-md);
    }

    .carousel-track {
      display: flex;
      gap: 20px;
      transition: transform 0.45s cubic-bezier(0.25, 0.46, 0.45, 0.94);
      will-change: transform;
    }

    .product-card {
      flex: 0 0 calc(25% - 15px);
      min-width: 240px;
      background: var(--cream);
      border-radius: var(--radius-md);
      overflow: hidden;
      transition: all 0.3s ease;
      border: 1px solid var(--cream-dark);
    }

    .product-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-lg);
    }

    .product-img {
      width: 100%;
      aspect-ratio: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 4rem;
      position: relative;
      overflow: hidden;
    }

    .product-img-granola { background: linear-gradient(145deg, #F9DEB3, #E9C46A); }
    .product-img-bagel { background: linear-gradient(145deg, #C9ACA6, #A27B5C); }
    .product-img-chocolate { background: linear-gradient(145deg, #6B3A2A, #3D1C0E); }
    .product-img-gnocchi { background: linear-gradient(145deg, #E8F5E9, #A5D6A7); }
    .product-img-chicken { background: linear-gradient(145deg, #FFE082, #FF8F00); }
    .product-img-cheddar { background: linear-gradient(145deg, #FFF9C4, #F9A825); }
    .product-img-mango { background: linear-gradient(145deg, #FFCC80, #FF6F00); }
    .product-img-almonds { background: linear-gradient(145deg, #D7CCC8, #795548); }

    .product-badge {
      position: absolute;
      top: 12px;
      left: 12px;
      background: var(--orange);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 0.7rem;
      padding: 3px 10px;
      border-radius: 100px;
    }

    .product-body {
      padding: 18px 20px 20px;
    }

    .product-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1rem;
      color: var(--text-dark);
      margin-bottom: 4px;
      line-height: 1.3;
    }

    .product-desc {
      font-size: 0.82rem;
      color: var(--text-light);
      margin-bottom: 14px;
      line-height: 1.5;
    }

    .product-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .product-price {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: 1.2rem;
      color: var(--green);
    }

    .btn-add {
      background: var(--green);
      color: var(--white);
      border: none;
      border-radius: 100px;
      padding: 7px 16px;
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 0.8rem;
      cursor: pointer;
      transition: all 0.2s ease;
    }

    .btn-add:hover {
      background: var(--green-light);
      transform: scale(1.05);
    }

    .carousel-controls {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      margin-top: 32px;
    }

    .carousel-btn {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: var(--white);
      border: 2px solid var(--green-pale);
      color: var(--green);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.2rem;
      transition: all 0.2s ease;
      box-shadow: var(--shadow-sm);
    }

    .carousel-btn:hover {
      background: var(--green);
      color: var(--white);
      border-color: var(--green);
      transform: scale(1.1);
    }

    .carousel-btn:disabled {
      opacity: 0.4;
      cursor: not-allowed;
      transform: none;
    }

    .carousel-dots {
      display: flex;
      gap: 6px;
    }

    .carousel-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--green-pale);
      transition: all 0.2s ease;
      cursor: pointer;
      border: none;
    }

    .carousel-dot.active {
      background: var(--green);
      width: 24px;
      border-radius: 4px;
    }

    /* ── BRAND HIGHLIGHTS ── */
    .highlights {
      background: var(--green);
      padding: 60px 24px;
    }

    .highlights-grid {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1px;
      background: rgba(255,255,255,0.1);
      border-radius: var(--radius-md);
      overflow: hidden;
    }

    .highlight-item {
      background: rgba(255,255,255,0.05);
      padding: 40px 32px;
      text-align: center;
      transition: background 0.2s ease;
    }

    .highlight-item:hover {
      background: rgba(255,255,255,0.1);
    }

    .highlight-number {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: clamp(2.2rem, 4vw, 3rem);
      color: var(--orange);
      margin-bottom: 6px;
      letter-spacing: -0.02em;
      line-height: 1;
    }

    .highlight-label {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      color: var(--white);
      margin-bottom: 6px;
    }

    .highlight-desc {
      font-size: 0.82rem;
      color: rgba(255,255,255,0.65);
      line-height: 1.5;
    }

    /* ── SEASONAL PICKS ── */
    .seasonal {
      background: linear-gradient(180deg, var(--cream) 0%, #FFF8E7 100%);
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }

    .seasonal-card {
      background: var(--white);
      border-radius: var(--radius-md);
      overflow: hidden;
      border: 1px solid var(--cream-dark);
      transition: all 0.3s ease;
    }

    .seasonal-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-lg);
    }

    .seasonal-img {
      width: 100%;
      aspect-ratio: 3/2;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
    }

    .seasonal-img-1 { background: linear-gradient(135deg, #C8E6C9, #69F0AE); }
    .seasonal-img-2 { background: linear-gradient(135deg, #FFE0B2, #FFAB40); }
    .seasonal-img-3 { background: linear-gradient(135deg, #D7CCC8, #6D4C41); }
    .seasonal-img-4 { background: linear-gradient(135deg, #F8BBD9, #E91E8C); }

    .seasonal-tag {
      display: inline-block;
      background: var(--orange);
      color: var(--white);
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 0.7rem;
      padding: 2px 10px;
      border-radius: 100px;
      margin-bottom: 8px;
      letter-spacing: 0.04em;
    }

    .seasonal-body {
      padding: 18px 20px 22px;
    }

    .seasonal-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1rem;
      color: var(--text-dark);
      margin-bottom: 6px;
      line-height: 1.3;
    }

    .seasonal-desc {
      font-size: 0.82rem;
      color: var(--text-light);
      margin-bottom: 14px;
      line-height: 1.5;
    }

    .seasonal-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .seasonal-price {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: 1.15rem;
      color: var(--green);
    }

    /* ── CATEGORIES ── */
    .categories {
      background: var(--white);
    }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 20px;
    }

    .category-card {
      position: relative;
      border-radius: var(--radius-md);
      overflow: hidden;
      aspect-ratio: 3/4;
      cursor: pointer;
      transition: transform 0.3s ease;
    }

    .category-card:hover {
      transform: scale(1.04);
      box-shadow: var(--shadow-lg);
    }

    .category-bg {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 4rem;
      transition: transform 0.3s ease;
    }

    .category-card:hover .category-bg {
      transform: scale(1.08);
    }

    .cat-snacks { background: linear-gradient(145deg, #FFADAD, #FF6B6B, #C1392B); }
    .cat-produce { background: linear-gradient(145deg, #B7E4C7, #52B788, #1B4332); }
    .cat-frozen { background: linear-gradient(145deg, #ADE8F4, #4CC9F0, #3A86FF); }
    .cat-beverages { background: linear-gradient(145deg, #FFD6A5, #FFAB40, #E65100); }
    .cat-dairy { background: linear-gradient(145deg, #E2E0FF, #9381FF, #6A4C93); }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0) 60%);
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      padding: 20px 18px;
      opacity: 0;
      transition: opacity 0.3s ease;
    }

    .category-card:hover .category-overlay {
      opacity: 1;
    }

    .category-name-overlay {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: 1.1rem;
      color: var(--white);
      margin-bottom: 4px;
    }

    .category-sub-overlay {
      font-size: 0.75rem;
      color: rgba(255,255,255,0.75);
      line-height: 1.4;
    }

    .category-label {
      text-align: center;
      padding: 14px 8px 6px;
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 0.95rem;
      color: var(--text-dark);
    }

    /* ── STORE LOCATOR ── */
    .store-locator {
      background: var(--cream);
      position: relative;
      overflow: hidden;
    }

    .store-locator::before {
      content: '';
      position: absolute;
      width: 600px; height: 600px;
      background: var(--green-pale);
      border-radius: 50%;
      top: -300px; right: -200px;
      pointer-events: none;
    }

    .store-locator-inner {
      max-width: 800px;
      margin: 0 auto;
      position: relative;
    }

    .store-search-box {
      display: flex;
      gap: 12px;
      margin-bottom: 32px;
    }

    .store-input {
      flex: 1;
      padding: 16px 22px;
      border: 2px solid var(--cream-dark);
      border-radius: 100px;
      font-family: 'Inter', sans-serif;
      font-size: 1rem;
      background: var(--white);
      color: var(--text-dark);
      outline: none;
      transition: border-color 0.2s ease;
    }

    .store-input:focus {
      border-color: var(--green);
      box-shadow: 0 0 0 4px rgba(45,106,79,0.1);
    }

    .store-input::placeholder { color: var(--text-light); }

    .store-search-btn {
      padding: 16px 32px;
      background: var(--green);
      color: var(--white);
      border: none;
      border-radius: 100px;
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1rem;
      cursor: pointer;
      transition: all 0.2s ease;
      white-space: nowrap;
    }

    .store-search-btn:hover {
      background: var(--green-light);
      transform: translateY(-2px);
      box-shadow: 0 4px 16px rgba(45,106,79,0.3);
    }

    .store-results {
      display: none;
      flex-direction: column;
      gap: 14px;
    }

    .store-results.visible { display: flex; }

    .store-result-card {
      background: var(--white);
      border: 1px solid var(--cream-dark);
      border-radius: var(--radius-md);
      padding: 22px 26px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      transition: all 0.3s ease;
      animation: slideIn 0.4s ease forwards;
    }

    .store-result-card:nth-child(2) { animation-delay: 0.08s; }
    .store-result-card:nth-child(3) { animation-delay: 0.16s; }

